// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address newOwner, address caller) public {
        vm.assume(caller != address(c) && caller != address(this));
        vm.assume(newOwner != address(0));
        address originalOwner = c.owner();
        vm.assume(caller != originalOwner);
        vm.prank(caller);
        try c.transferOwnership(newOwner) {} catch {}
        assertTrue(c.owner() == originalOwner);
    }
}
